import adsk.core, adsk.fusion, adsk.cam

def run(_context):
    app = adsk.core.Application.get()
    doc = app.activeDocument
    cam = adsk.cam.CAM.cast(doc.products.itemByProductType('CAMProductType'))

    setup = cam.setups.item(0)
    sp = setup.parameters

    # Read current WCS parameter expressions
    wcs_params = [
        'wcs_orientation_mode', 'wcs_origin_mode', 'wcs_origin_boxPoint',
        'job_stockMode', 'job_stockOffsetMode', 'job_stockOffsetSides',
        'job_stockOffsetTop', 'job_stockOffsetBottom'
    ]

    print('Current WCS/stock parameter values:')
    for pname in wcs_params:
        try:
            p = sp.itemByName(pname)
            if p:
                try:
                    val = p.value.value
                    expr = p.value.expression
                    print(f'  {pname}: value={val:.4f}, expr={expr}')
                except:
                    try:
                        print(f'  {pname}: expr={p.value.expression}')
                    except:
                        print(f'  {pname}: <no expression>')
            else:
                print(f'  {pname}: NOT FOUND')
        except Exception as e:
            print(f'  {pname}: ERROR - {e}')

