import adsk.core, adsk.fusion, adsk.cam
import time

def run(_context):
    app = adsk.core.Application.get()
    doc = app.activeDocument
    cam = adsk.cam.CAM.cast(doc.products.itemByProductType('CAMProductType'))

    setup = cam.setups.item(0)

    # Check ALL operations
    for i in range(setup.operations.count):
        op = setup.operations.item(i)
        print(f'Op[{i}] {op.name}: hasToolpath={op.hasToolpath}, valid={op.isToolpathValid}')
        # Get ALL errors including non-editable
        editable_errors = []
        non_editable_key_errors = []
        for j in range(op.parameters.count):
            p = op.parameters.item(j)
            if p.error:
                if p.isEditable:
                    editable_errors.append(f'  EDITABLE [{p.name}]: {p.error}')
                else:
                    # Only report key non-editable ones
                    if p.name in ['clearanceHeight_ref', 'retractHeight_ref', 
                                   'topHeight_ref', 'bottomHeight_ref', 'feedHeight_ref',
                                   'fineStepdown', 'smoothingFilterTolerance', 'reducedFeedDistance',
                                   'restMaterialShoulderLength']:
                        non_editable_key_errors.append(f'  NON-EDIT [{p.name}]: {p.error}')
        if editable_errors:
            for e in editable_errors:
                print(e)
        if non_editable_key_errors:
            for e in non_editable_key_errors:
                print(e)
        if not editable_errors and not non_editable_key_errors:
            print('  No key errors')

