import adsk.core, adsk.fusion, adsk.cam

def run(_context):
    app = adsk.core.Application.get()
    doc = app.activeDocument
    cam = adsk.cam.CAM.cast(doc.products.itemByProductType('CAMProductType'))

    setup = cam.setups.item(0)

    # Check all ops for any editable errors
    print('All editable errors after generation:')
    for i in range(setup.operations.count):
        op_i = setup.operations.item(i)
        errs = []
        for j in range(op_i.parameters.count):
            p2 = op_i.parameters.item(j)
            if p2.error and p2.isEditable:
                errs.append(f'[{p2.name}]: {p2.error} | "{p2.expression}"')
        if errs:
            print(f'Op[{i}] {op_i.name}: {len(errs)} errors')
            for e in errs:
                print(f'  {e}')
        else:
            print(f'Op[{i}] {op_i.name}: NO editable errors')

    # Also check non-editable errors that look important
    print('\nKey non-editable errors:')
    for i in range(setup.operations.count):
        op_i = setup.operations.item(i)
        for j in range(op_i.parameters.count):
            p2 = op_i.parameters.item(j)
            if p2.error and not p2.isEditable:
                name = p2.name
                # Only show critical-looking ones
                if any(kw in name for kw in ['height_ref', 'fineStep', 'smoothing', 'reducedFeed',
                                              'Shoulder', 'noEngagement']):
                    print(f'  Op[{i}] [{name}]: {p2.error}')

